design_text:
{
  "site_summary": "A full-sun, low-moisture, sun-baked courtyard designed to withstand heat and accommodate a dog that digs and rubs.",
  "layout_strategy": "The scheme is structured into three height layers stacked against the courtyard wall: an upright architectural focal point in the mid layer, a low sprawling ground layer of tough herbs and perennials at floor level, and a trailing accent layer cascading from wall-mounted pots just above dog height.",
  "combination_logic": "The plants combine upright architectural forms with fine, needle-like textures and soft sprawling mats, creating a striking contrast against harsh stone walls. Silvery foliage and bright yellow or purple summer blooms offer a Mediterranean aesthetic that intensifies under baking sun and changes with seasonal flowering.",
  "zones": [
    {
      "zone_name": "Mid-Level Architectural Focal Point",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "Against the sun-baked back wall in full, unrelenting southern sun, elevated in heavy stone containers out of direct dog reach.",
      "plants": [
        {
          "scientific_name": "Beaucarnea recurvata",
          "common_name": "Pony Tail Palm",
          "why": "Extremely drought tolerant and stores water in its swollen base, perfect for baking sun.",
          "role_in_combination": "Provides a strong architectural vertical silhouette and cascading ribbon-like leaves that contrast sharply with stiff shrubs."
        },
        {
          "scientific_name": "Rosmarinus officinalis",
          "common_name": "Rosemary",
          "why": "Thrives in dry, hot conditions and forms a robust woody structure.",
          "role_in_combination": "Adds woody height, aromatic pine scent when brushed against, and pale blue flowers in spring."
        }
      ],
      "maintenance": [
        "Water thoroughly only when the soil is completely dry",
        "Prune rosemary lightly after flowering to maintain shape",
        "Repot the ponytail palm every 3 to 4 years into a slightly larger container"
      ]
    },
    {
      "zone_name": "Ground Grazing and Sprawling Edge",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "Along the courtyard floor perimeter in full sun, easily accessible for the household dog to interact with.",
      "plants": [
        {
          "scientific_name": "Thymus vulgaris",
          "common_name": "Thyme",
          "why": "Low-growing, intensely aromatic, and tolerant of occasional trampling or light nibbling by a dog.",
          "role_in_combination": "Forms a dense, aromatic ground carpet that releases scent when stepped on and complements the upright shrubs."
        },
        {
          "scientific_name": "Achillea millefolium",
          "common_name": "Yarrow",
          "why": "Tough perennial that handles poor, dry soils and spreads to fill gaps.",
          "role_in_combination": "Introduces feathery, fern-like foliage texture and flat-topped flower clusters that contrast with needle leaves."
        }
      ],
      "maintenance": [
        "Water sparingly once established to encourage deep root growth",
        "Trim back thyme after flowering to prevent woody centers",
        "Divide yarrow in early spring if it spreads too aggressively"
      ]
    },
    {
      "zone_name": "Hanging and Sprawling Cascade",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "Mounted on high wall brackets, receiving full sun and completely out of reach of the dog.",
      "plants": [
        {
          "scientific_name": "Sanvitalia spp.",
          "common_name": "Creeping Zinnia",
          "why": "Loves baking sun and cascades beautifully over container edges in dry conditions.",
          "role_in_combination": "Provides brilliant yellow daisy-like flowers that cascade downwards, contrasting with the neutral greens of the lower zones."
        }
      ],
      "maintenance": [
        "Check daily for moisture during peak summer heat as hanging baskets dry out fast",
        "Feed with a balanced liquid fertilizer monthly in summer",
        "Deadhead spent flowers regularly to encourage continuous blooming"
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Deep watering of established ground and mid-layer containers",
      "frequency": "Once every 7 to 10 days in peak summer, and every 3 weeks in winter",
      "season": "Summer and Autumn"
    },
    {
      "task": "Pruning and shaping woody herbs like rosemary",
      "frequency": "Once a year after the main flowering period",
      "season": "Spring"
    },
    {
      "task": "Checking wall brackets and hanging baskets for structural security",
      "frequency": "Monthly before high winds or storms",
      "season": "All seasons"
    }
  ],
  "care_cautions": [
    "Overwatering the Pony Tail Palm or Rosemary in the mid-layer containers can quickly cause fatal root rot due to poor drainage in heavy heat.",
    "The trailing Sanvitalia in the hanging baskets will scorch and dry out within hours if neglected during a severe heatwave.",
    "While thyme and yarrow are robust, intense digging by the dog directly at the base of the ground layer can expose and damage fragile root systems."
  ],
  "pet_safety_note": "The pet-accessible grazing zone features safe, non-toxic aromatic herbs like thyme, while toxic or delicate plants are safely elevated out of reach in wall containers."
}
